        // Track scroll state for sticky elements
        var hasScrolled = false;

        var scrollHandler = function() {
            var scrollTop = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop;
            var stickyElements = document.querySelectorAll('.sticky-mobile');
            var shouldScroll = scrollTop > 1;

            if (shouldScroll !== hasScrolled) {
                hasScrolled = shouldScroll;
                var method = shouldScroll ? 'add' : 'remove';
                stickyElements.forEach(function(el) {
                    el.classList[method]('is-scrolled');
                });
            }
        };

        document.addEventListener('DOMContentLoaded', function() {
            document.body.addEventListener('scroll', scrollHandler, false);
            document.querySelectorAll('[class*="container"], [class*="wrapper"]').forEach(function(el) {
                el.addEventListener('scroll', scrollHandler, false);
            });
        });

        $(function() {
            /* take over tooltips with bs5 */
            $('.has-tooltip, .has-tooltip-body').tooltip();

            /* allow html5 form validation and bs5 classes to work */
            $('form.needs-validation').on('submit', function (event) {
                var form = $(this);
                if (!form[0].checkValidity()) {
                    event.preventDefault();
                    event.stopPropagation();
                }
                form.addClass('was-validated');
            });

            copyPublicNavigationBarLinksToMobile();
            copyPublicHeaderNavLinksToMobile($('.header-desktop').find('.main-nav'));
