            copyPublicHeaderNavLinksToMobile($('.header-desktop').find('.main-sub-nav'));
            addMobileUtilityLinks();

            // allow cart navlink to open minicart
            $(document).on('click', '#mobileShoppingCartTrigger', function(e) {
