        function moveModalsOutOfDesktopHeader() {
            $('header').append($('#rec1-policies-modal'));
            $('header').append($('#rec1-forgot-password-modal'));
            $('header').append($('#rec1-help-modal'));
        }

        function copyPublicNavigationBarLinksToMobile() {
            var $mobileNav = $('#offcanvasMenuMain').find('.offcanvas-body .main-nav-sections')[0];
            var $offcanvasBody = $('#offcanvasMenuMain .offcanvas-body .main-nav-sections');
            $('.rec1-public-navigation-group').each(function () {
                var $n = $(document.createElement('div'));
                var $a = $(this).clone();
                $a.removeClass();
                $n.append($a);
                $n.appendTo($mobileNav);
            });
        }

        function copyPublicHeaderNavLinksToMobile(elements) {
            var $offcanvasBody = $('#offcanvasMenuMain .offcanvas-body .main-nav-sections');

            // Create a wrapper only once
            var $bottomSection = $('#mobile-extra-links');
            if ($bottomSection.length === 0) {
                $bottomSection = $('<div id="mobile-extra-links" class="mobile-extra-links"></div>');
                $offcanvasBody.append($bottomSection);
            }

            elements.each(function () {
                var $ul = $(this).clone();
                $ul.removeClass();
                $ul.addClass('list-unstyled mobile-extra-list');
                $ul.removeAttr('id');

                // Remove styles from child li elements
                $ul.find('li').removeClass().removeAttr('style');

                $bottomSection.append($ul);
            });
        }

        function addMobileUtilityLinks() {
            var $offcanvasBody = $('#offcanvasMenuMain .offcanvas-body');

            // Create wrapper only once
            var $utilitySection = $('#mobile-utility-links');
            if ($utilitySection.length === 0) {
                $utilitySection = $('<div id="mobile-utility-links" class="mobile-utility-links"></div>');
                $offcanvasBody.append($utilitySection);
            }

            // Move logout link from top to bottom of mobile menu
            var $logoutLink = $('.rec1-public-navigation-group a.rec1-logout-trigger').first().clone();
            if ($logoutLink.length) {
                $logoutLink.removeClass().addClass('mobile-utility-link');
                $utilitySection.append($logoutLink);
            }

            $('#offcanvasMenuMain a.rec1-logout-trigger').remove();

            // Collapse menu link
            var $collapse = $(`<a href="#" class="mobile-utility-link"><i class="fa-solid fa-chevron-left"></i><span> Collapse Menu</span></a>`);

            $collapse.on('click', function (e) {
                e.preventDefault();
                var bsOffcanvas = bootstrap.Offcanvas.getInstance(document.getElementById('offcanvasMenuMain'));
                if (bsOffcanvas) {
                    bsOffcanvas.hide();
                }
            });

            $utilitySection.append($collapse);
        }

        function wrapResponsiveTables(root) {
            var scope = root || document.getElementById('rec1-public-wrapper') || document.body;
            scope.querySelectorAll('table').forEach(function (table) {
                if (table.closest('.table-responsive')) {
                    return;
                }

                // Skip system tables entirely - don't wrap or style them
                var hasSystemClasses = table.classList.contains('ui-table') ||
                    table.classList.contains('interactive-grid-table') ||
                    table.closest('.rec1-catalog-item-info');

                if (hasSystemClasses) {
                    return; // Skip this table completely
                }

                // Detect if this is a TinyMCE table:
                // 1. Has inline width style (TinyMCE adds width percentages)
                // 2. Is in a content area (descriptions)
                var hasInlineWidth = table.style.width && table.style.width !== '';
                var inContentArea = table.closest('.rec1-catalog-group-details') ||
                    table.closest('.rec1-catalog-item-description') ||
                    table.closest('.rec1-catalog-item-content') ||
                    table.closest('.rec1-catalog-tab-body');

                var isTinyMCE = hasInlineWidth && inContentArea;

                // table.classList.add('table', 'table-sm');

                if (isTinyMCE) {
                    table.classList.add('rec1-tinymce-table');

                    // Force inline width with !important to override Bootstrap
                    // Preserve original inline width by reading it and re-applying with !important
                    var inlineWidth = table.style.width;
                    if (inlineWidth) {
                        table.style.setProperty('width', inlineWidth, 'important');
                    }

                    // If table has border attribute, ensure cells get proper borders
                    if (table.hasAttribute('border') && table.getAttribute('border') !== '0') {
                        var borderWidth = table.style.borderWidth || '1px';
                        var borderStyle = table.style.borderStyle || 'solid';
                        var borderColor = table.style.borderColor || '#000';

                        // Apply border to all cells if not already styled
                        table.querySelectorAll('td, th').forEach(function(cell) {
                            if (!cell.style.border && !cell.style.borderWidth) {
                                cell.style.border = borderWidth + ' ' + borderStyle + ' ' + borderColor;
                            }
                        });
                    }
                }

                var wrapper = document.createElement('div');
                wrapper.className = 'table-responsive';
                table.parentNode.insertBefore(wrapper, table);
                wrapper.appendChild(table);
            });
        }

        // Set active menu item based on current path
        $(function () {
            const currentURL = window.location.pathname.toLowerCase();

            $('#offcanvasMenuMain a').each(function () {
                const href = $(this).attr('href');

                // Ignore empty links or modal triggers
                if (!href || href === '#' || href.startsWith('#')) {
                    return;
                }

                // Convert to absolute pathname
                const linkPath = new URL(href, window.location.origin).pathname.toLowerCase();

                // Exact match only
                if (linkPath === currentURL) {
                    $(this).addClass('active');
                }
            });

            wrapResponsiveTables();

            var observer = new MutationObserver(function (mutations) {
                var needsRun = mutations.some(function (m) {
                    return Array.prototype.some.call(m.addedNodes || [], function (node) {
                        return node.nodeType === 1 && node.querySelector && node.querySelector('table');
                    });
                });
                if (needsRun) {
                    wrapResponsiveTables();
                }
            });
            observer.observe(document.getElementById('rec1-public-wrapper') || document.body, { childList: true, subtree: true });
        });
     
     
     

     
 
 
     
         







